options.helpers:
return (function () {
  'use strict';

  var PANEL_ID = 'certificate-panel-130';
  var HELPER_NAME = 'certificateDashboard130';
  var DAY = 24 * 60 * 60 * 1000;
  var rawRows = data && Array.isArray(data.data) ? data.data : [];

  var state = {
    draft: {
      commonName: '',
      keyAlgorithm: 'all',
      signatureAlgorithm: 'all',
      subject: '',
      expiry: 'all',
      selfSigned: 'all',
      keyStrength: 'all',
      issuer: 'all',
      entityType: 'all'
    },
    applied: {
      commonName: '',
      keyAlgorithm: 'all',
      signatureAlgorithm: 'all',
      subject: '',
      expiry: 'all',
      selfSigned: 'all',
      keyStrength: 'all',
      issuer: 'all',
      entityType: 'all'
    }
  };

  function text(value) {
    return value == null ? '' : String(value).trim();
  }

  function escapeHtml(value) {
    return text(value)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#039;');
  }

  function escapeAttribute(value) {
    return escapeHtml(value).replace(/`/g, '&#096;');
  }

  function firstValue(row, names) {
    var index;
    var value;
    if (!row) {
      return '';
    }
    for (index = 0; index < names.length; index += 1) {
      if (Object.prototype.hasOwnProperty.call(row, names[index])) {
        value = row[names[index]];
        if (value !== null && value !== undefined && text(value) !== '') {
          return value;
        }
      }
    }
    return '';
  }

  function normaliseFieldName(value) {
    return text(value).toLowerCase().replace(/[^a-z0-9]+/g, '');
  }

  function isLikelyKeyAlgorithm(value) {
    var raw = text(value);
    var compact;

    if (!raw || raw.length > 80) {
      return false;
    }

    if (/^\d{10,13}$/.test(raw) || /^\d{4}[-\/]\d{1,2}[-\/]\d{1,2}/.test(raw)) {
      return false;
    }

    if (/[=,;\n]/.test(raw)) {
      return false;
    }

    compact = raw.toLowerCase().replace(/[^a-z0-9]+/g, '');

    if (compact === 'id') {
      return true;
    }

    return /^(rsa|rsapublickey|rsa\d+|ec|ecpublickey|ecdsa|dsa|dsapublickey|ed25519|ed448|x25519|x448|dh|dhpublickey)$/.test(compact) ||
      /^(rsa|ec|ecdsa|dsa|ed|x|dh)[a-z0-9]*$/.test(compact);
  }

  function findKeyAlgorithm(row) {
    var direct = firstValue(row, [
      'public_key_algorithm',
      'key_algorithm',
      'Public Key Algorithm',
      'Key Algorithm',
      'publicKeyAlgorithm',
      'keyAlgorithm',
      '#public_key_algorithm',
      '#key_algorithm'
    ]);
    var keys;
    var index;
    var fieldName;
    var normalised;
    var value;

    if (text(direct)) {
      return text(direct);
    }

    keys = Object.keys(row || {});

    for (index = 0; index < keys.length; index += 1) {
      fieldName = keys[index];
      normalised = normaliseFieldName(fieldName);
      if (normalised.indexOf('publickeyalgorithm') !== -1 ||
          normalised.indexOf('keyalgorithm') !== -1) {
        value = text(row[fieldName]);
        if (value) {
          return value;
        }
      }
    }

    /* Discovery labels unnamed expressions differently depending on the
     * returned field set. Work backwards through all logical-expression
     * columns and identify the value by shape rather than a fragile suffix.
     */
    for (index = keys.length - 1; index >= 0; index -= 1) {
      fieldName = keys[index];
      normalised = normaliseFieldName(fieldName);
      value = row[fieldName];
      if (normalised.indexOf('logicalexpression') !== -1 && isLikelyKeyAlgorithm(value)) {
        return text(value);
      }
    }

    return 'Unknown';
  }

  function unpackRow(row) {
    if (!row || typeof row !== 'object') {
      return {};
    }
    if (row.result && typeof row.result === 'object' && !Array.isArray(row.result)) {
      var merged = {};
      Object.keys(row.result).forEach(function (key) {
        merged[key] = row.result[key];
      });
      Object.keys(row).forEach(function (key) {
        if (key !== 'result' && !Object.prototype.hasOwnProperty.call(merged, key)) {
          merged[key] = row[key];
        }
      });
      return merged;
    }
    return row;
  }

  function parseDate(value) {
    var parsed;
    var numeric;
    var raw;

    if (value instanceof Date && !Number.isNaN(value.getTime())) {
      return value;
    }

    raw = text(value);
    if (!raw || raw === 'null' || raw === 'undefined' || raw.toLowerCase() === 'invalid time') {
      return null;
    }

    if (/^\d{10,13}$/.test(raw)) {
      numeric = Number(raw);
      if (raw.length === 10) {
        numeric *= 1000;
      }
      parsed = new Date(numeric);
      return Number.isNaN(parsed.getTime()) ? null : parsed;
    }

    parsed = new Date(raw);
    return Number.isNaN(parsed.getTime()) ? null : parsed;
  }

  function startOfToday() {
    var now = new Date();
    return new Date(now.getFullYear(), now.getMonth(), now.getDate());
  }

  function formatDate(value) {
    var date = value instanceof Date ? value : parseDate(value);
    if (!date) {
      return 'Not available';
    }
    return date.toLocaleDateString('en-GB', {
      day: '2-digit',
      month: 'short',
      year: 'numeric'
    });
  }

  function formatNumber(value) {
    var number = Number(value);
    return Number.isFinite(number) ? number.toLocaleString('en-GB') : '0';
  }

  function normaliseBoolean(value) {
    var raw = text(value).toLowerCase();
    if (value === true || raw === 'true' || raw === 'yes' || raw === '1') {
      return 'yes';
    }
    if (value === false || raw === 'false' || raw === 'no' || raw === '0') {
      return 'no';
    }
    return 'unknown';
  }

  function parseKeySize(value) {
    var match = text(value).replace(/,/g, '').match(/\d+/);
    return match ? Number(match[0]) : null;
  }

  function parseEntityTypes(value) {
    var source = value;
    var parts = [];
    var seen = {};

    function addPart(part) {
      var cleaned = text(part)
        .replace(/^['"\s]+|['"\s]+$/g, '')
        .trim();
      var key;

      if (!cleaned) {
        return;
      }

      key = cleaned.toLowerCase();
      if (!seen[key]) {
        seen[key] = true;
        parts.push(cleaned);
      }
    }

    if (Array.isArray(source)) {
      source.forEach(function (part) {
        parseEntityTypes(part).forEach(addPart);
      });
      return parts;
    }

    source = text(source);
    if (!source) {
      return parts;
    }

    if (source.charAt(0) === '[' && source.charAt(source.length - 1) === ']') {
      try {
        var parsed = JSON.parse(source);
        if (Array.isArray(parsed)) {
          parsed.forEach(function (part) {
            parseEntityTypes(part).forEach(addPart);
          });
          return parts;
        }
      } catch (ignore) {
        source = source.slice(1, -1);
      }
    }

    source.split(/[,;|\n]+/).forEach(addPart);
    return parts;
  }

  function expiryStatus(date) {
    var days;
    if (!date) {
      return {
        key: 'unknown',
        label: 'No expiry date',
        className: 'unknown',
        days: null,
        rank: 5
      };
    }

    days = Math.ceil((date.getTime() - startOfToday().getTime()) / DAY);

    if (days < 0) {
      return {
        key: 'expired',
        label: 'Expired',
        className: 'expired',
        days: days,
        rank: 0
      };
    }
    if (days <= 7) {
      return {
        key: 'due7',
        label: days === 0 ? 'Expires today' : 'Due within 7 days',
        className: 'due7',
        days: days,
        rank: 1
      };
    }
    if (days <= 30) {
      return {
        key: 'due30',
        label: 'Due within 30 days',
        className: 'due30',
        days: days,
        rank: 2
      };
    }
    if (days <= 90) {
      return {
        key: 'due90',
        label: 'Due within 90 days',
        className: 'due90',
        days: days,
        rank: 3
      };
    }
    return {
      key: 'healthy',
      label: 'More than 90 days',
      className: 'healthy',
      days: days,
      rank: 4
    };
  }

  function relativeExpiry(row, status) {
    var supplied = text(row.relative);
    var absoluteDays;

    if (supplied && supplied.toLowerCase() !== 'invalid time') {
      return supplied;
    }
    if (status.days === null) {
      return 'Unknown';
    }
    if (status.days === 0) {
      return 'Today';
    }
    if (status.days < 0) {
      absoluteDays = Math.abs(status.days);
      return formatNumber(absoluteDays) + (absoluteDays === 1 ? ' day ago' : ' days ago');
    }
    return 'In ' + formatNumber(status.days) + (status.days === 1 ? ' day' : ' days');
  }

  function keyStrength(keySize) {
    if (keySize === null) {
      return {
        key: 'unknown',
        label: 'Unknown',
        className: 'unknown'
      };
    }
    if (keySize < 2048) {
      return {
        key: 'weak',
        label: keySize + ' bit',
        className: 'weak'
      };
    }
    if (keySize === 2048) {
      return {
        key: 'standard',
        label: keySize + ' bit',
        className: 'standard'
      };
    }
    return {
      key: 'strong',
      label: keySize + ' bit',
      className: 'strong'
    };
  }

  var rows = rawRows.map(function (rawRow, index) {
    var row = unpackRow(rawRow);
    var expiry = parseDate(firstValue(row, ['expiry_date', 'Expiry Date', 'expiry', 'Expiry']));
    var keySize = parseKeySize(firstValue(row, ['public_key_size', 'Public Key Size', 'key_size']));
    var item = {
      index: index,
      kind: text(firstValue(row, ['#kind', 'kind', 'Type'])) || 'Certificate',
      issuer: text(firstValue(row, ['issuer', 'Issuer'])) || 'Unknown issuer',
      commonName: text(firstValue(row, ['common_name', 'Common Name', 'commonName'])) || 'Unnamed certificate',
      subject: text(firstValue(row, ['subject', 'Subject'])) || '',
      startDate: parseDate(firstValue(row, ['start_date', 'created_at', 'Logical expression', 'Start Date'])),
      expiryDate: expiry,
      relative: text(firstValue(row, ['Function whenWasThat', 'whenWasThat', 'expiry_relative', 'Relative Expiry'])),
      signatureAlgorithm: text(firstValue(row, ['signature_algorithm', 'Signature Algorithm', 'signatureAlgorithm'])) || 'Unknown',
      keyAlgorithm: findKeyAlgorithm(row),
      keySize: keySize,
      selfSigned: normaliseBoolean(firstValue(row, ['self_signed', 'Self Signed', 'selfSigned'])),
      entityType: text(firstValue(row, [
        'Function kind',
        'function kind',
        'Entity Type',
        'entity_type',
        'entityType',
        'kind(#Certificate:Certificate:ElementWithCertificate:)',
        'kind(#Certificate:Certificate:ElementWithCertificate)'
      ])) || 'Unknown entity'
    };
    item.entityTypes = parseEntityTypes(item.entityType);
    if (!item.entityTypes.length) {
      item.entityTypes = ['Unknown entity'];
    }
    item.entityType = item.entityTypes.join(', ');
    item.expiryStatus = expiryStatus(item.expiryDate);
    item.keyStrength = keyStrength(item.keySize);
    return item;
  });

  function copyFilters(filters) {
    return {
      commonName: filters.commonName,
      keyAlgorithm: filters.keyAlgorithm,
      signatureAlgorithm: filters.signatureAlgorithm,
      subject: filters.subject,
      expiry: filters.expiry,
      selfSigned: filters.selfSigned,
      keyStrength: filters.keyStrength,
      issuer: filters.issuer,
      entityType: filters.entityType
    };
  }

  function matchesExpiry(status, filter) {
    if (filter === 'all') {
      return true;
    }
    if (filter === 'due30') {
      return status.key === 'due7' || status.key === 'due30';
    }
    if (filter === 'due90') {
      return status.key === 'due7' || status.key === 'due30' || status.key === 'due90';
    }
    return status.key === filter;
  }

  function filteredRows(filters) {
    var commonNameNeedle = text(filters.commonName).toLowerCase();
    var subjectNeedle = text(filters.subject).toLowerCase();

    return rows.filter(function (row) {
      return (!commonNameNeedle || row.commonName.toLowerCase().indexOf(commonNameNeedle) !== -1) &&
        (filters.keyAlgorithm === 'all' || row.keyAlgorithm === filters.keyAlgorithm) &&
        (filters.signatureAlgorithm === 'all' || row.signatureAlgorithm === filters.signatureAlgorithm) &&
        (!subjectNeedle || row.subject.toLowerCase().indexOf(subjectNeedle) !== -1) &&
        matchesExpiry(row.expiryStatus, filters.expiry) &&
        (filters.selfSigned === 'all' || row.selfSigned === filters.selfSigned) &&
        (filters.keyStrength === 'all' || row.keyStrength.key === filters.keyStrength) &&
        (filters.issuer === 'all' || row.issuer === filters.issuer) &&
        (filters.entityType === 'all' || row.entityTypes.indexOf(filters.entityType) !== -1);
    });
  }

  function sortedRows(list) {
    return list.slice().sort(function (left, right) {
      var statusDifference = left.expiryStatus.rank - right.expiryStatus.rank;
      var leftDate;
      var rightDate;

      if (statusDifference) {
        return statusDifference;
      }

      leftDate = left.expiryDate ? left.expiryDate.getTime() : Number.MAX_SAFE_INTEGER;
      rightDate = right.expiryDate ? right.expiryDate.getTime() : Number.MAX_SAFE_INTEGER;

      return leftDate - rightDate || left.commonName.localeCompare(right.commonName);
    });
  }

  function countByExpiry(keys) {
    return rows.filter(function (row) {
      return keys.indexOf(row.expiryStatus.key) !== -1;
    }).length;
  }

  function countSelfSigned() {
    return rows.filter(function (row) {
      return row.selfSigned === 'yes';
    }).length;
  }

  function uniqueIssuers() {
    var seen = {};
    return rows
      .map(function (row) {
        return row.issuer;
      })
      .filter(function (issuer) {
        if (!issuer || seen[issuer]) {
          return false;
        }
        seen[issuer] = true;
        return true;
      })
      .sort(function (left, right) {
        return left.localeCompare(right);
      });
  }

  function uniqueEntityTypes() {
    var seen = {};
    var entityTypes = [];

    rows.forEach(function (row) {
      row.entityTypes.forEach(function (entityType) {
        var key = entityType.toLowerCase();
        if (!seen[key]) {
          seen[key] = true;
          entityTypes.push(entityType);
        }
      });
    });

    return entityTypes.sort(function (left, right) {
      return left.localeCompare(right);
    });
  }

  function uniqueKeyAlgorithms() {
    var seen = {};
    return rows
      .map(function (row) {
        return row.keyAlgorithm;
      })
      .filter(function (algorithm) {
        var key = text(algorithm).toLowerCase();
        if (!key || seen[key]) {
          return false;
        }
        seen[key] = true;
        return true;
      })
      .sort(function (left, right) {
        if (left === 'Unknown') {
          return 1;
        }
        if (right === 'Unknown') {
          return -1;
        }
        return left.localeCompare(right);
      });
  }


  function uniqueSignatureAlgorithms() {
    var seen = {};
    return rows
      .map(function (row) {
        return row.signatureAlgorithm;
      })
      .filter(function (algorithm) {
        var key = text(algorithm).toLowerCase();
        if (!key || seen[key]) {
          return false;
        }
        seen[key] = true;
        return true;
      })
      .sort(function (left, right) {
        if (left === 'Unknown') {
          return 1;
        }
        if (right === 'Unknown') {
          return -1;
        }
        return left.localeCompare(right);
      });
  }

  function selected(value, current) {
    return value === current ? ' selected' : '';
  }

  function discoveryBaseUrl() {
    var resolved;
    try {
      resolved = text(replaceVariables('$disco_url'));
    } catch (ignore) {
      resolved = '';
    }
    if (!resolved || resolved === '$disco_url' || resolved.indexOf('$disco_url') !== -1) {
      return '';
    }
    return resolved.replace(/\/+$/, '');
  }

  function discoveryUrl(commonName) {
    var base = discoveryBaseUrl();
    var safeName;
    var query;

    if (!base || !commonName) {
      return '';
    }

    safeName = commonName
      .replace(/\\/g, '\\\\')
      .replace(/'/g, "\\'");
    query = "search Certificate where common_name = '" + safeName + "'";
    return base + '/NodeSearch?query=' + encodeURIComponent(query);
  }

  function renderColumnFilters() {
    var issuerOptions = uniqueIssuers().map(function (issuer) {
      return '<option value="' + escapeAttribute(issuer) + '"' +
        selected(issuer, state.draft.issuer) + '>' + escapeHtml(issuer) + '</option>';
    }).join('');
    var entityTypeOptions = uniqueEntityTypes().map(function (entityType) {
      return '<option value="' + escapeAttribute(entityType) + '"' +
        selected(entityType, state.draft.entityType) + '>' + escapeHtml(entityType) + '</option>';
    }).join('');
    var keyAlgorithmOptions = uniqueKeyAlgorithms().map(function (algorithm) {
      return '<option value="' + escapeAttribute(algorithm) + '"' +
        selected(algorithm, state.draft.keyAlgorithm) + '>' + escapeHtml(algorithm) + '</option>';
    }).join('');

    var signatureAlgorithmOptions = uniqueSignatureAlgorithms().map(function (algorithm) {
      return '<option value="' + escapeAttribute(algorithm) + '"' +
        selected(algorithm, state.draft.signatureAlgorithm) + '>' + escapeHtml(algorithm) + '</option>';
    }).join('');

    return '<tr class="cert-column-filter-row" aria-label="Column filters">' +
      '<th><select class="cert-header-filter cert-expiry-filter" aria-label="Filter status">' +
      '<option value="all"' + selected('all', state.draft.expiry) + '>All</option>' +
      '<option value="expired"' + selected('expired', state.draft.expiry) + '>Expired</option>' +
      '<option value="due7"' + selected('due7', state.draft.expiry) + '>≤ 7 days</option>' +
      '<option value="due30"' + selected('due30', state.draft.expiry) + '>≤ 30 days</option>' +
      '<option value="due90"' + selected('due90', state.draft.expiry) + '>≤ 90 days</option>' +
      '<option value="healthy"' + selected('healthy', state.draft.expiry) + '>Healthy</option>' +
      '<option value="unknown"' + selected('unknown', state.draft.expiry) + '>Unknown</option>' +
      '</select></th>' +

      '<th><input class="cert-header-filter cert-column-text-filter cert-common-filter" type="search" ' +
      'value="' + escapeAttribute(state.draft.commonName) + '" placeholder="Search…" ' +
      'aria-label="Filter common name" title="Applies when you leave the field or press Enter"></th>' +

      '<th><select class="cert-header-filter cert-entity-filter" aria-label="Filter entity type">' +
      '<option value="all"' + selected('all', state.draft.entityType) + '>All types</option>' +
      entityTypeOptions + '</select></th>' +

      '<th><select class="cert-header-filter cert-issuer-filter" aria-label="Filter issuer">' +
      '<option value="all"' + selected('all', state.draft.issuer) + '>All issuers</option>' +
      issuerOptions + '</select></th>' +

      '<th><span class="cert-filter-spacer" aria-hidden="true">—</span></th>' +
      '<th><span class="cert-filter-spacer" aria-hidden="true">—</span></th>' +

      '<th><select class="cert-header-filter cert-key-filter" aria-label="Filter public key size">' +
      '<option value="all"' + selected('all', state.draft.keyStrength) + '>All sizes</option>' +
      '<option value="weak"' + selected('weak', state.draft.keyStrength) + '>&lt; 2048</option>' +
      '<option value="standard"' + selected('standard', state.draft.keyStrength) + '>2048</option>' +
      '<option value="strong"' + selected('strong', state.draft.keyStrength) + '>&gt; 2048</option>' +
      '<option value="unknown"' + selected('unknown', state.draft.keyStrength) + '>Unknown</option>' +
      '</select></th>' +

      '<th><select class="cert-header-filter cert-key-algorithm-filter" aria-label="Filter key algorithm">' +
      '<option value="all"' + selected('all', state.draft.keyAlgorithm) + '>All algorithms</option>' +
      keyAlgorithmOptions + '</select></th>' +

      '<th><select class="cert-header-filter cert-algorithm-filter" aria-label="Filter signature algorithm">' +
      '<option value="all"' + selected('all', state.draft.signatureAlgorithm) + '>All signatures</option>' +
      signatureAlgorithmOptions + '</select></th>' +

      '<th><select class="cert-header-filter cert-self-filter" aria-label="Filter self-signed">' +
      '<option value="all"' + selected('all', state.draft.selfSigned) + '>All</option>' +
      '<option value="yes"' + selected('yes', state.draft.selfSigned) + '>Yes</option>' +
      '<option value="no"' + selected('no', state.draft.selfSigned) + '>No</option>' +
      '<option value="unknown"' + selected('unknown', state.draft.selfSigned) + '>Unknown</option>' +
      '</select></th>' +

      '<th><input class="cert-header-filter cert-column-text-filter cert-subject-filter" type="search" ' +
      'value="' + escapeAttribute(state.draft.subject) + '" placeholder="Search…" ' +
      'aria-label="Filter subject" title="Applies when you leave the field or press Enter"></th>' +
      '</tr>';
  }

  function renderKpis() {
    var expired = countByExpiry(['expired']);
    var due30 = countByExpiry(['due7', 'due30']);
    var selfSigned = countSelfSigned();
    var cards = [
      {
        key: 'all',
        tone: 'cyan',
        label: 'Certificates',
        value: rows.length,
        note: 'Complete inventory'
      },
      {
        key: 'expired',
        tone: 'red',
        label: 'Expired',
        value: expired,
        note: 'Immediate review'
      },
      {
        key: 'due30',
        tone: 'orange',
        label: 'Due within 30 days',
        value: due30,
        note: 'Renewal window'
      },
      {
        key: 'selfsigned',
        tone: 'purple',
        label: 'Self-signed',
        value: selfSigned,
        note: 'Trust review'
      }
    ];

    return '<section class="cert-kpis" aria-label="Certificate summary">' +
      cards.map(function (card) {
        var active = (card.key === 'all' &&
          state.applied.expiry === 'all' &&
          state.applied.selfSigned === 'all') ||
          (card.key === state.applied.expiry) ||
          (card.key === 'selfsigned' && state.applied.selfSigned === 'yes');

        return '<button type="button" class="cert-kpi cert-tone-' + card.tone +
          (active ? ' cert-is-active' : '') + '" data-cert-kpi="' + card.key + '">' +
          '<span class="cert-kpi-label">' + escapeHtml(card.label) + '</span>' +
          '<strong class="cert-kpi-value">' + formatNumber(card.value) + '</strong>' +
          '<span class="cert-kpi-note">' + escapeHtml(card.note) + '</span>' +
          '</button>';
      }).join('') +
      '</section>';
  }

  function renderStatus(row) {
    return '<span class="cert-status cert-status-' + row.expiryStatus.className + '">' +
      escapeHtml(row.expiryStatus.label) + '</span>';
  }

  function renderSelfSigned(value) {
    var label = value === 'yes' ? 'Yes' : value === 'no' ? 'No' : 'Unknown';
    return '<span class="cert-boolean cert-boolean-' + value + '">' + label + '</span>';
  }

  function renderKey(row) {
    return '<span class="cert-key cert-key-' + row.keyStrength.className + '">' +
      escapeHtml(row.keyStrength.label) + '</span>';
  }

  function renderEntityType(values) {
    var types = Array.isArray(values) && values.length ? values : ['Unknown entity'];

    return '<div class="cert-entity-types">' + types.map(function (value) {
      var safeClass = text(value).toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
      return '<span class="cert-entity-type cert-entity-' + escapeAttribute(safeClass || 'unknown') +
        '" title="' + escapeAttribute(value) + '">' + escapeHtml(value) + '</span>';
    }).join('') + '</div>';
  }

  function renderKeyAlgorithm(value) {
    var algorithm = text(value) || 'Unknown';
    var safeClass = algorithm.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');

    return '<span class="cert-key-algorithm cert-key-algorithm-' +
      escapeAttribute(safeClass || 'unknown') + '">' + escapeHtml(algorithm) + '</span>';
  }

  function renderCommonName(row) {
    var url = discoveryUrl(row.commonName);
    if (!url) {
      return '<span class="cert-common-name">' + escapeHtml(row.commonName) + '</span>';
    }
    return '<a class="cert-common-link" href="' + escapeAttribute(url) +
      '" target="_blank" rel="noopener noreferrer" title="Open certificate in BMC Discovery">' +
      '<span>' + escapeHtml(row.commonName) + '</span>' +
      '<span class="cert-launch-icon" aria-hidden="true">↗</span></a>';
  }

  function renderTable(list) {
    if (!list.length) {
      return '<div class="cert-empty">' +
        '<strong>No certificates match the applied filters.</strong>' +
        '<span>Clear or adjust the filters to restore the inventory.</span>' +
        '</div>';
    }

    return '<div class="cert-table-wrap">' +
      '<table class="cert-table">' +
      '<thead><tr class="cert-heading-row">' +
      '<th>Status</th>' +
      '<th>Common name</th>' +
      '<th>Entity type</th>' +
      '<th>Issuer</th>' +
      '<th>Expiry date</th>' +
      '<th>Remaining</th>' +
      '<th>Public key size</th>' +
      '<th>Key algorithm</th>' +
      '<th>Signature algorithm</th>' +
      '<th>Self-signed</th>' +
      '<th>Subject</th>' +
      '</tr>' + renderColumnFilters() + '</thead>' +
      '<tbody>' +
      list.map(function (row) {
        return '<tr class="cert-row cert-row-' + row.expiryStatus.className + '">' +
          '<td>' + renderStatus(row) + '</td>' +
          '<td>' + renderCommonName(row) + '</td>' +
          '<td>' + renderEntityType(row.entityTypes) + '</td>' +
          '<td><span class="cert-issuer" title="' + escapeAttribute(row.issuer) + '">' +
          escapeHtml(row.issuer) + '</span></td>' +
          '<td><span class="cert-date">' + escapeHtml(formatDate(row.expiryDate)) + '</span></td>' +
          '<td><span class="cert-relative">' + escapeHtml(relativeExpiry(row, row.expiryStatus)) + '</span></td>' +
          '<td>' + renderKey(row) + '</td>' +
          '<td>' + renderKeyAlgorithm(row.keyAlgorithm) + '</td>' +
          '<td><span class="cert-algorithm">' + escapeHtml(row.signatureAlgorithm) + '</span></td>' +
          '<td>' + renderSelfSigned(row.selfSigned) + '</td>' +
          '<td><span class="cert-subject" title="' + escapeAttribute(row.subject || 'Not available') + '">' +
          escapeHtml(row.subject || 'Not available') + '</span></td>' +
          '</tr>';
      }).join('') +
      '</tbody></table></div>';
  }

  function filtersArePending() {
    return JSON.stringify(state.draft) !== JSON.stringify(state.applied);
  }

  function render() {
    var list = sortedRows(filteredRows(state.applied));
    var baseConfigured = !!discoveryBaseUrl();

    return '<div class="cert-shell">' +
      '<header class="cert-header">' +
      '<div>' +
      '<div class="cert-eyebrow">BMC Helix Discovery</div>' +
      '<h2>Certificate Inventory</h2>' +
      '<p>Prioritise expiry risk, inspect certificate properties and open the selected certificate in Discovery.</p>' +
      '</div>' +
      '<div class="cert-header-meta">' +
      '<span class="cert-result-count"><strong>' + formatNumber(list.length) + '</strong> of ' +
      formatNumber(rows.length) + ' shown</span>' +
      '<span class="cert-link-state ' + (baseConfigured ? 'cert-link-ready' : 'cert-link-missing') + '">' +
      (baseConfigured ? 'Discovery cross-launch ready' : '$disco_url is not resolved') +
      '</span></div></header>' +

      renderKpis() +

      '<section class="cert-results">' +
      '<div class="cert-results-head">' +
      '<div><h3>Certificate details</h3>' +
      '<span>Ordered by expiry risk, then expiry date · filters apply automatically from the controls beneath each column heading</span>' +
      '<span class="cert-filter-state cert-filter-applied">Filters apply automatically</span></div>' +
      '<div class="cert-results-actions">' +
      '<span class="cert-results-count">' + formatNumber(list.length) + ' records</span>' +
      '<button class="cert-clear" type="button" data-cert-action="clear">Clear</button>' +
      '</div></div>' +
      renderTable(list) +
      '</section>' +
      '</div>';
  }

  function rootForEvent(event) {
    if (!event || !event.target || !event.target.closest) {
      return null;
    }
    return event.target.closest('#' + PANEL_ID);
  }

  function captureScroll(root) {
    var wrap = root ? root.querySelector('.cert-table-wrap') : null;
    return wrap ? {
      top: wrap.scrollTop,
      left: wrap.scrollLeft
    } : {
      top: 0,
      left: 0
    };
  }

  function restoreScroll(root, position) {
    var wrap = root ? root.querySelector('.cert-table-wrap') : null;
    if (wrap) {
      wrap.scrollTop = position.top;
      wrap.scrollLeft = position.left;
    }
  }

  function rerender(root, preserveScroll) {
    var position = preserveScroll ? captureScroll(root) : {
      top: 0,
      left: 0
    };
    root.innerHTML = render();
    if (preserveScroll) {
      restoreScroll(root, position);
    }
  }

  function updateDraftFromControl(target) {
    if (target.classList.contains('cert-common-filter')) {
      state.draft.commonName = target.value || '';
      return true;
    }
    if (target.classList.contains('cert-key-algorithm-filter')) {
      state.draft.keyAlgorithm = target.value || 'all';
      return true;
    }
    if (target.classList.contains('cert-algorithm-filter')) {
      state.draft.signatureAlgorithm = target.value || 'all';
      return true;
    }
    if (target.classList.contains('cert-subject-filter')) {
      state.draft.subject = target.value || '';
      return true;
    }
    if (target.classList.contains('cert-expiry-filter')) {
      state.draft.expiry = target.value || 'all';
      return true;
    }
    if (target.classList.contains('cert-self-filter')) {
      state.draft.selfSigned = target.value || 'all';
      return true;
    }
    if (target.classList.contains('cert-key-filter')) {
      state.draft.keyStrength = target.value || 'all';
      return true;
    }
    if (target.classList.contains('cert-issuer-filter')) {
      state.draft.issuer = target.value || 'all';
      return true;
    }
    if (target.classList.contains('cert-entity-filter')) {
      state.draft.entityType = target.value || 'all';
      return true;
    }
    return false;
  }

  function applyFilters(root) {
    state.applied = copyFilters(state.draft);
    rerender(root, true);
  }

  function clearFilters(root) {
    state.draft = {
      commonName: '',
      keyAlgorithm: 'all',
      signatureAlgorithm: 'all',
      subject: '',
      expiry: 'all',
      selfSigned: 'all',
      keyStrength: 'all',
      issuer: 'all',
      entityType: 'all'
    };
    state.applied = copyFilters(state.draft);
    rerender(root, false);
  }

  function markFiltersPending(root) {
    var notice = root ? root.querySelector('.cert-filter-state') : null;
    if (notice) {
      notice.className = 'cert-filter-state cert-filter-pending';
      notice.textContent = 'Text filter applies when you leave the field or press Enter';
    }
  }

  function onInput(event) {
    var root = rootForEvent(event);
    if (!root || !event.target.classList.contains('cert-column-text-filter')) {
      return;
    }
    updateDraftFromControl(event.target);
    markFiltersPending(root);
  }

  function onChange(event) {
    var root = rootForEvent(event);
    if (!root || !updateDraftFromControl(event.target)) {
      return;
    }
    applyFilters(root);
  }

  function onKeydown(event) {
    var root = rootForEvent(event);
    if (!root || !event.target.classList.contains('cert-column-text-filter') || event.key !== 'Enter') {
      return;
    }
    event.preventDefault();
    updateDraftFromControl(event.target);
    applyFilters(root);
  }

  function onClick(event) {
    var root = rootForEvent(event);
    var target;
    var action;
    var kpi;

    if (!root) {
      return;
    }

    target = event.target.closest('[data-cert-action], [data-cert-kpi]');
    if (!target || !root.contains(target)) {
      return;
    }

    action = target.getAttribute('data-cert-action');
    if (action === 'clear') {
      clearFilters(root);
      return;
    }

    kpi = target.getAttribute('data-cert-kpi');
    if (!kpi) {
      return;
    }

    if (kpi === 'all') {
      state.draft.expiry = 'all';
      state.draft.selfSigned = 'all';
    } else if (kpi === 'selfsigned') {
      state.draft.selfSigned = 'yes';
      state.draft.expiry = 'all';
    } else {
      state.draft.expiry = kpi;
      state.draft.selfSigned = 'all';
    }
    state.applied = copyFilters(state.draft);
    rerender(root, false);
  }

  if (handlebars.unregisterHelper) {
    handlebars.unregisterHelper(HELPER_NAME);
  }

  handlebars.registerHelper(HELPER_NAME, function () {
    return new handlebars.SafeString(render());
  });

  document.addEventListener('input', onInput);
  document.addEventListener('change', onChange);
  document.addEventListener('keydown', onKeydown);
  document.addEventListener('click', onClick);

  return function () {
    document.removeEventListener('input', onInput);
    document.removeEventListener('change', onChange);
    document.removeEventListener('keydown', onKeydown);
    document.removeEventListener('click', onClick);
    if (handlebars.unregisterHelper) {
      handlebars.unregisterHelper(HELPER_NAME);
    }
  };
}());

