/* Certificate Inventory
 * Dynamic Text 4.0.0
 * Version: v0.008
 */

.certificate-page {
  width: 100%;
  height: 100%;
  min-height: 360px;
  color: #f8fafc;
  font-family: Arial, Helvetica, sans-serif;
}

.certificate-page,
.certificate-page *,
.certificate-page *::before,
.certificate-page *::after {
  box-sizing: border-box;
}

.cert-shell {
  --cert-bg: #111827;
  --cert-panel: #151f2e;
  --cert-panel-soft: #1b2637;
  --cert-border: #2d3a4b;
  --cert-border-soft: #243244;
  --cert-text: #f8fafc;
  --cert-muted: #9ca8b8;
  --cert-cyan: #6bd4da;
  --cert-teal: #00827d;
  --cert-green: #22c55e;
  --cert-amber: #f1a425;
  --cert-orange: #fb923c;
  --cert-red: #ef4444;
  --cert-purple: #a78bfa;

  width: 100%;
  min-height: 100%;
  padding: 14px;
  overflow: hidden;
  color: var(--cert-text);
  background:
    radial-gradient(circle at 92% 0%, rgba(107, 212, 218, 0.10), transparent 28%),
    radial-gradient(circle at 8% 0%, rgba(99, 39, 84, 0.10), transparent 24%),
    var(--cert-bg);
  border: 1px solid var(--cert-border);
  border-radius: 10px;
}

.cert-header {
  display: flex;
  gap: 18px;
  align-items: flex-start;
  justify-content: space-between;
  margin-bottom: 12px;
}

.cert-eyebrow {
  margin-bottom: 4px;
  color: var(--cert-cyan);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.cert-header h2 {
  margin: 0 0 5px;
  color: var(--cert-text);
  font-size: 21px;
  line-height: 1.15;
}

.cert-header p {
  max-width: 760px;
  margin: 0;
  color: var(--cert-muted);
  font-size: 11px;
  line-height: 1.45;
}

.cert-header-meta {
  display: flex;
  flex: 0 0 auto;
  gap: 7px;
  align-items: flex-end;
  flex-direction: column;
}

.cert-result-count,
.cert-link-state,
.cert-results-count {
  display: inline-flex;
  gap: 4px;
  align-items: center;
  min-height: 25px;
  padding: 5px 9px;
  border: 1px solid var(--cert-border);
  border-radius: 999px;
  color: var(--cert-muted);
  background: rgba(21, 31, 46, 0.88);
  font-size: 9px;
  font-weight: 700;
  white-space: nowrap;
}

.cert-result-count strong {
  color: var(--cert-text);
  font-size: 11px;
}

.cert-link-ready {
  color: #bbf7d0;
  border-color: rgba(34, 197, 94, 0.34);
  background: rgba(22, 101, 52, 0.14);
}

.cert-link-missing {
  color: #fde68a;
  border-color: rgba(241, 164, 37, 0.38);
  background: rgba(146, 64, 14, 0.15);
}

.cert-kpis {
  display: grid;
  grid-template-columns: repeat(4, minmax(125px, 1fr));
  gap: 8px;
  margin-bottom: 10px;
}

.cert-kpi {
  position: relative;
  min-width: 0;
  padding: 9px 10px 8px;
  overflow: hidden;
  color: inherit;
  text-align: left;
  background: linear-gradient(180deg, rgba(27, 38, 55, 0.98), rgba(21, 31, 46, 0.98));
  border: 1px solid var(--cert-border);
  border-radius: 9px;
  cursor: pointer;
  transition: transform 120ms ease, border-color 120ms ease, background 120ms ease;
}

.cert-kpi::before {
  position: absolute;
  top: 0;
  right: 0;
  left: 0;
  height: 2px;
  content: "";
  background: var(--cert-tone);
  opacity: 0.82;
}

.cert-kpi:hover {
  transform: translateY(-1px);
  border-color: var(--cert-tone);
  background: linear-gradient(180deg, rgba(31, 45, 64, 0.98), rgba(21, 31, 46, 0.98));
}

.cert-kpi.cert-is-active {
  border-color: var(--cert-tone);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--cert-tone) 35%, transparent);
}

.cert-tone-cyan { --cert-tone: var(--cert-cyan); }
.cert-tone-red { --cert-tone: var(--cert-red); }
.cert-tone-orange { --cert-tone: var(--cert-orange); }
.cert-tone-purple { --cert-tone: var(--cert-purple); }

.cert-kpi-label,
.cert-kpi-note {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.cert-kpi-label {
  color: var(--cert-muted);
  font-size: 9px;
  font-weight: 700;
}

.cert-kpi-value {
  display: block;
  margin: 3px 0 2px;
  color: var(--cert-text);
  font-size: 20px;
  line-height: 1;
}

.cert-kpi-note {
  color: var(--cert-tone);
  font-size: 8px;
  font-weight: 700;
}

.cert-results-actions {
  display: flex;
  flex: 0 0 auto;
  gap: 6px;
  align-items: center;
}

.cert-clear {
  height: 27px;
  padding: 0 10px;
  border-radius: 6px;
  font-family: inherit;
  font-size: 8px;
  font-weight: 800;
  white-space: nowrap;
  cursor: pointer;
}

.cert-clear {
