  border: 1px solid #3b4b61;
}

.cert-clear:hover {
  color: #ffffff;
  border-color: #64748b;
}

.cert-filter-state {
  display: inline-flex;
  align-items: center;
  margin-left: 8px;
  padding-left: 8px;
  border-left: 1px solid var(--cert-border);
  font-size: 8px;
  font-weight: 700;
  line-height: 1.35;
}

.cert-filter-applied {
  color: #7dd3fc;
}

.cert-filter-pending {
  color: #fde68a;
}

.cert-results {
  overflow: hidden;
  background: rgba(15, 23, 42, 0.42);
  border: 1px solid var(--cert-border);
  border-radius: 9px;
}

.cert-results-head {
  display: flex;
  gap: 12px;
  align-items: center;
  justify-content: space-between;
  min-height: 43px;
  padding: 8px 10px;
  border-bottom: 1px solid var(--cert-border);
