  display: inline-flex;
  align-items: center;
  min-height: 20px;
  padding: 3px 7px;
  color: #cfe2ff;
  background: rgba(30, 64, 175, 0.15);
  border: 1px solid rgba(96, 165, 250, 0.34);
  border-radius: 999px;
  font-size: 8px;
  font-weight: 800;
  white-space: nowrap;
}

.cert-key-algorithm-unknown {
  color: #cbd5e1;
  background: rgba(71, 85, 105, 0.18);
  border-color: #475569;
}

.cert-common-name {
  color: #d9f8fa;
  font-weight: 800;
}

.cert-common-link {
  display: inline-flex;
  gap: 5px;
  align-items: center;
  max-width: 290px;
  overflow: hidden;
  color: #7de7ec;
  font-weight: 850;
  text-decoration: none;
}

.cert-common-link > span:first-child {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.cert-common-link:hover {
  color: #c8fbfd;
  text-decoration: underline;
  text-underline-offset: 2px;
}

.cert-launch-icon {
  flex: 0 0 auto;
  color: var(--cert-cyan);
  font-size: 10px;
}

.cert-issuer,
.cert-subject {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.cert-issuer {
  max-width: 240px;
  color: #d8e0ea;
}

.cert-subject {
  max-width: 280px;
  color: #9fb0c5;
  font-family: Consolas, "Courier New", monospace;
  font-size: 8px;
}

.cert-date {
  color: #e5e7eb;
  white-space: nowrap;
}

.cert-relative {
  color: #a9bad0;
  white-space: nowrap;
}

.cert-algorithm {
  display: block;
  max-width: 170px;
  overflow: hidden;
  color: #cfe2ff;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.cert-empty {
  display: flex;
  gap: 5px;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  min-height: 170px;
  padding: 24px;
  color: var(--cert-muted);
  text-align: center;
}

.cert-empty strong {
  color: var(--cert-text);
  font-size: 11px;
}

.cert-empty span {
  font-size: 9px;
}

.cert-table-wrap::-webkit-scrollbar {
  width: 10px;
  height: 10px;
}

.cert-table-wrap::-webkit-scrollbar-thumb {
  background: #3b4b61;
  border: 2px solid #111827;
  border-radius: 10px;
}

.cert-table-wrap::-webkit-scrollbar-track {
  background: #0d1524;
}

@media (max-width: 900px) {
  .cert-header {
    flex-direction: column;
  }

  .cert-header-meta {
    align-items: flex-start;
    flex-direction: row;
    flex-wrap: wrap;
  }

  .cert-kpis {
    grid-template-columns: repeat(2, minmax(125px, 1fr));
  }

  .cert-results-head {
    align-items: flex-start;
    flex-direction: column;
  }

  .cert-results-actions {
    width: 100%;
  }

  .cert-results-count {
    margin-right: auto;
  }
}

@media (max-width: 580px) {
  .cert-shell {
    padding: 10px;
  }

  .cert-kpis {
    grid-template-columns: 1fr;
  }

  .cert-results-actions {
    flex-wrap: wrap;
  }
}
